MIN_VERSIONS = {'macOS': 13, 'Windows': 1809, 'Linux': 20.04}
LOGINS = ('pro', 'max', 'team', 'enterprise', 'console')


def check_env(env):
    need = MIN_VERSIONS[env['os']]
    if env['os_version'] < need:
        return ['\u7cfb\u7edf\u7248\u672c\u8fc7\u4f4e']
    if env['memory_gb'] < 4:
        return ['\u5185\u5b58\u4e0d\u8db3']
    if not env['network']:
        return ['\u65e0\u6cd5\u8fde\u63a5\u6a21\u578b\u670d\u52a1']
    if env['login'] not in LOGINS:
        return ['\u767b\u5f55\u65b9\u5f0f\u4e0d\u53ef\u7528']
    if env['os'] == 'Windows' and not env.get('git_bash') and not env.get('powershell'):
        return ['\u7f3a\u5c11 Bash \u5de5\u5177']
    return []

print(check_env({'os': 'macOS', 'os_version': 13, 'memory_gb': 8,
                 'network': True, 'login': 'pro'}))

